use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let intervals = input.as_array().unwrap();
    let mut total_length = 0;
    for interval in intervals {
        let start = interval.as_array().unwrap().get(0).unwrap().as_i64().unwrap();
        let end = interval.as_array().unwrap().get(1).unwrap().as_i64().unwrap();
        total_length += end - start + 1;
    }
    Value::from(total_length)
}
